function getCsrfToken(){const e=document.cookie.split(";").map(e=>e.trim()).find(e=>e.startsWith("csrf_token="));return e?decodeURIComponent(e.slice(11)):""}async function fetchWithCsrf(e,t={}){if(["POST","PUT","DELETE"].includes((t.method||"GET").toUpperCase())){t.headers=t.headers||{};const e=getCsrfToken();e&&(t.headers["X-CSRF-Token"]=e)}return fetch(e,{credentials:"same-origin",...t})}async function parseJsonSafe(e){return e.json()}export const API_URL="/api/data";export const LOGIN_URL="/api/login";export const LOGOUT_URL="/api/logout";export const CHANGE_PASSWORD_URL="/api/change-password";export const PUSH_REGISTER_URL="/api/push/register";export const PUSH_UNREGISTER_URL="/api/push/unregister";export async function loadDataFromServer(e=null){try{const t=null==e?"":`?childId=${encodeURIComponent(e)}`,r=await fetchWithCsrf(`/api/data${t}`);if(r.ok)return await parseJsonSafe(r)}catch(e){console.error("Failed to load from server:",e)}return null}export async function loadBaseData(){try{const e=await fetchWithCsrf("/api/base-data");if(e.ok)return await parseJsonSafe(e)}catch(e){console.error("Failed to load base data:",e)}return{tasks:[],products:[]}}export async function saveDataToServer(e){try{const t=await fetchWithCsrf(API_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(e)});if(!t.ok){let e="";try{const r=await parseJsonSafe(t.clone());e=r?.error?`: ${r.error}`:""}catch(e){}console.error(`Failed to save data (${t.status})${e}`)}return t.ok}catch(e){return console.error("Failed to save to server:",e),!1}}export async function logout(){try{return(await fetchWithCsrf(LOGOUT_URL,{method:"POST"})).ok}catch(e){return console.error("Logout failed:",e),!1}}export async function registerPushTokenOnServer(e){try{const t=await fetchWithCsrf(PUSH_REGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(e)});return t.ok?{success:!0}:await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function unregisterPushTokenOnServer(e){try{const t=await fetchWithCsrf(PUSH_UNREGISTER_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:e})});return t.ok?{success:!0}:await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function changePassword(e,t){try{const r=await fetchWithCsrf(CHANGE_PASSWORD_URL,{method:"POST",headers:{"Content-Type":"application/json"},cache:"no-store",body:JSON.stringify({oldPassword:e,newPassword:t})});if(r.ok)return{success:!0};return{success:!1,error:(await parseJsonSafe(r)).error}}catch(e){return{success:!1,error:"Ошибка сети"}}}export async function login(e,t){try{const r=await fetchWithCsrf(LOGIN_URL,{method:"POST",headers:{"Content-Type":"application/json"},cache:"no-store",body:JSON.stringify({email:e,password:t})});if(r.ok){return{success:!0,role:(await parseJsonSafe(r)).role}}return{success:!1,error:(await parseJsonSafe(r)).error,status:r.status}}catch(e){return{success:!1,error:"Network Error"}}}export async function regenerateChildToken(e){try{const t=await fetchWithCsrf(`/api/children/${e}/regenerate-token`,{method:"POST"});if(t.ok)return await parseJsonSafe(t)}catch(e){console.error("Failed to regenerate token:",e)}return null}export async function addChild(e){try{const t=await fetchWithCsrf("/api/children",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:e})});return await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function deleteChild(e){try{const t=await fetchWithCsrf(`/api/children/${e}`,{method:"DELETE"});return await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function getChildLink(e){try{const t=await fetchWithCsrf(`/api/children/${e}/link`);return await parseJsonSafe(t)}catch(e){return{success:!1,error:"Network error"}}}export async function updateChildSettings(e,t,r){try{const e=await fetchWithCsrf(`/api/children/${t}/settings`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});return await parseJsonSafe(e)}catch(e){return console.error("Failed to update child settings:",e),{success:!1,error:"Network error"}}}export async function updateNickname(e){try{const t=await fetchWithCsrf("/api/update-nickname",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({nickname:e})});return await parseJsonSafe(t)}catch(e){return console.error("Failed to update nickname:",e),{success:!1,error:"Ошибка сети"}}}export async function searchUsers(e){try{const t=await fetchWithCsrf(`/api/search-user?nickname=${encodeURIComponent(e)}`);if(t.ok)return await parseJsonSafe(t)}catch(e){console.error("Failed to search users:",e)}return[]}export async function addFriend(e){try{const t=await fetchWithCsrf("/api/add-friend",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({friendId:e})});return await parseJsonSafe(t)}catch(e){return console.error("Failed to add friend:",e),{success:!1,error:"Ошибка сети"}}}export async function loadFriendsList(){try{const e=await fetchWithCsrf("/api/friends-list");if(e.ok)return await parseJsonSafe(e)}catch(e){console.error("Failed to load friends list:",e)}return[]}export async function savePreference(e,t){try{return(await fetchWithCsrf("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:e,value:t})})).ok}catch(e){return console.error("Failed to save preference:",e),!1}}export async function saveChildTheme(e,t){try{return(await fetchWithCsrf(`/api/children/${e}/theme`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({theme:t})})).ok}catch(e){return console.error("Failed to save child theme:",e),!1}}export async function fetchAnalyticsData(e="month",t=null){try{let r=`/api/analytics?timeframe=${e}`;t&&(r+=`&childId=${t}`);const o=await fetchWithCsrf(r);if(o.ok)return await parseJsonSafe(o)}catch(e){console.error("Failed to fetch analytics:",e)}return null}